-- A failed session's kind, typed where it was found (core `LastErrorKind`),
-- beside the words a person reads: what `relaunchOf` and every other
-- decision about the row reads, never `last_error`. Rows written before this
-- carried the kind only in the hub's own words, so those words are read here
-- once, and never again: CLAUDE_CONVERSATION_GONE is `conversation-gone`,
-- RESTART_LOST is `restart-lost`. Generated by drizzle-kit; the two UPDATEs
-- are written by hand.
ALTER TABLE `instances` ADD `last_error_kind` text;--> statement-breakpoint
UPDATE `instances` SET `last_error_kind` = 'conversation-gone' WHERE `last_error` = 'This Claude Code conversation is gone and cannot be resumed. Start a new session to continue working.';--> statement-breakpoint
UPDATE `instances` SET `last_error_kind` = 'restart-lost' WHERE `last_error` = 'The agent restarted, and this session left nothing to resume from.';
